import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateNotificationDto } from './dto/create-notification.dto';
@Injectable()
export class NotificationsService { constructor(private readonly prisma: PrismaService) {} create(dto: CreateNotificationDto) { return this.prisma.notification.create({ data: dto }); } findAll(recipientId: string, unreadOnly = false) { return this.prisma.notification.findMany({ where: { recipientId, ...(unreadOnly ? { isRead: false } : {}) }, orderBy: { createdAt: 'desc' } }); } async markRead(id: string) { const notification = await this.prisma.notification.findUnique({ where: { id } }); if (!notification) throw new NotFoundException('Notification not found'); return this.prisma.notification.update({ where: { id }, data: { isRead: true } }); } markAllRead(recipientId: string) { return this.prisma.notification.updateMany({ where: { recipientId, isRead: false }, data: { isRead: true } }); } }
